// Parses the LOOKUP_RESULT_JSON line(s) the patchmon_lookup.yml playbook prints, e.g.
// LOOKUP_RESULT_JSON: {"hostname":"web2","groups":["nginx","debian_hosts"],"is_proxmox_guest":true,"proxmox_node":"proxmox1","proxmox_vmtype":"qemu","proxmox_vmid":142,"in_alert_cooldown":false}
//
// Hardened 2026-07-13 (v1): patchmon_lookup.yml runs with 'hosts: all', so if Semaphore's Limit
// option isn't constraining the run, multiple LOOKUP_RESULT_JSON lines can appear -- this scans
// all of them and matches on hostname instead of blindly taking the first line.
//
// Hardened 2026-07-13 (v2): Ansible's 'debug: msg:' task prints as ok: [host] => { "msg": "..." },
// which JSON-escapes every quote inside the message (LOOKUP_RESULT_JSON: {\"hostname\": ...).
// JSON.parse() on that raw captured text throws (invalid JSON), and the try/catch below silently
// swallowed it -- producing lookupHostCount: 0 even when the line was right there in the log. Now
// un-escaping \" -> " across the whole text before searching/parsing fixes that.
const targetHostname = $('Normalize Trigger Payload').first().json.hostname;
const text = ($input.first().json.output || '').replace(/\\"/g, '"');
const re = /LOOKUP_RESULT_JSON:\s*(\{.*\})/g;
let m;
const candidates = [];
while ((m = re.exec(text)) !== null) {
  try { candidates.push(JSON.parse(m[1])); } catch (e) { /* skip unparsable line */ }
}
let parsed = candidates.find(c => (c.hostname || '').toLowerCase() === (targetHostname || '').toLowerCase());
const matchedCorrectHost = !!parsed;
if (!parsed) parsed = candidates[0] || {};

return [{ json: {
  ...$('Normalize Trigger Payload').first().json,
  groups: parsed.groups || [],
  isProxmoxGuest: !!parsed.is_proxmox_guest,
  proxmoxNode: parsed.proxmox_node || '',
  proxmoxType: parsed.proxmox_vmtype || '',
  proxmoxVmid: parsed.proxmox_vmid || '',
  inAlertCooldown: !!parsed.in_alert_cooldown,
  lookupStatus: $input.first().json.status,
  lookupHostCount: candidates.length,
  lookupMatchedCorrectHost: matchedCorrectHost
} }];

// Priority-ordered: first matching rule wins. Edit freely as your fleet grows.
// Fallback lockKeyGroup is null -> lockKey becomes '', meaning no cluster-style group lock applies; 
// Patchmon_tag_host.yml self-guards against duplicate webhooks for the same host via its own-tag check.
const rules = [
  { group: 'galera',        template: $('Global Config').first().json.SEMAPHORE_TEMPLATE_GALERA,  lockKeyGroup: 'cluster_a' },
  { group: 'cluster_a',     template: $('Global Config').first().json.SEMAPHORE_TEMPLATE_GALERA,  lockKeyGroup: 'cluster_a' },
  { group: 'cluster_b',     template: $('Global Config').first().json.SEMAPHORE_TEMPLATE_GALERA,  lockKeyGroup: 'cluster_b' },
  { group: 'nginx',         template: $('Global Config').first().json.SEMAPHORE_TEMPLATE_NGINX,   lockKeyGroup: 'nginx' },
  { group: 'debian_hosts',  template: $('Global Config').first().json.SEMAPHORE_TEMPLATE_DEBIAN,  lockKeyGroup: null },
];
const groups = $json.groups || [];
let chosen = null;
for (const r of rules) {
  if (groups.includes(r.group)) { chosen = r; break; }
}
if (!chosen) {
  chosen = { group: 'unmatched', template: $('Global Config').first().json.SEMAPHORE_TEMPLATE_DEBIAN, lockKeyGroup: null };
}
const lockKey = chosen.lockKeyGroup || '';

// node - success/partial/failure messages included - can read securityOnlyUpdate directly
// instead of each re-deriving it from SECURITY_ONLY_GROUPS + groups separately.
const securityOnlyGroups = (($('Global Config').first().json.SECURITY_ONLY_GROUPS || '')
  .split(/[,\n]/).map(g => g.trim().toLowerCase()).filter(g => g.length > 0));
const securityOnlyUpdate = securityOnlyGroups.some(g => groups.map(x => x.toLowerCase()).includes(g));

return [{ json: { ...$json, semaphoreTemplateId: chosen.template, matchedRule: chosen.group, lockKey, securityOnlyUpdate } }];

