// Parses the TAG_RESULT_JSON line(s) the patchmon_tag_host.yml playbook prints, e.g.
// TAG_RESULT_JSON: {"hostname":"mail1","action":"add","lockMethod":"proxmox_tag","locked":true,"blocked_reason":null,"staleLockReclaimed":false,"tags":[...]}
//
// Hardened 2026-08-06: patchmon_tag_host.yml runs with 'hosts: all', relying on Semaphore's
// Limit option to scope execution to just the target host -- same design as patchmon_lookup.yml,
// which we already found can silently run against the whole inventory if Limit isn't actually
// constraining it. This now scans every TAG_RESULT_JSON line and matches on hostname instead of
// blindly taking the first one, same pattern as Parse Group Names. Previously, if Limit ran loose
// and another host's line appeared earlier in the raw output, this would read THAT host's lock
// result as if it were the target's -- consistent with a case where Ansible correctly wrote the
// tag on the target host but Lock Acquired? still evaluated false.
//
// Also keeps the existing quote-unescaping fix for Ansible's debug: msg: JSON-escaping behavior.
const targetHostname = $('Decide Template + Lock Key').first().json.hostname;
const text = ($input.first().json.output || '').replace(/\\"/g, '"');
const re = /TAG_RESULT_JSON:\s*(\{.*\})/g;
let m;
const candidates = [];
while ((m = re.exec(text)) !== null) {
  try { candidates.push(JSON.parse(m[1])); } catch (e) { /* skip unparsable line */ }
}
let parsed = candidates.find(c => (c.hostname || '').toLowerCase() === (targetHostname || '').toLowerCase());
const matchedCorrectHost = !!parsed;
if (!parsed) parsed = candidates[0] || {};

return [{ json: {
  ...$('Decide Template + Lock Key').first().json,
  locked: !!parsed.locked,
  blockedReason: parsed.blocked_reason || null,
  staleLockReclaimed: !!parsed.staleLockReclaimed,
  tagResultHostCount: candidates.length,
  tagResultMatchedCorrectHost: matchedCorrectHost
} }];

