// Parses PATCH_VERIFY_JSON from the patch playbook's output, e.g.
// PATCH_VERIFY_JSON: {"hostname":"web2","still_pending_count":2,"still_pending_packages":["nginx","libssl3"],"other_pending_count":9,"other_pending_packages":[...],"security_only_update":true,"agent_present":true}
//
// Hardened 2026-08-06: same hostname-matching fix as Parse Tag-Add Result / Parse Group Names --
// patch_debian_*.yml plays scope to a group (debian_hosts/nginx/galera) and rely on Semaphore's
// Limit to narrow further to one host. If Limit isn't constraining the run, other hosts in that
// group could emit their own PATCH_VERIFY_JSON lines in the same output -- taking the first match
// blindly risked reading a different host's verification result. Now scans all lines and matches
// on hostname, same pattern used elsewhere.
//
// 2026-07-13: quote-unescaping fix retained -- was silently defaulting stillPendingCount to -1
// (agent_present:false path) whenever JSON.parse choked on Ansible's escaped quotes.
//
// 2026-08-13: still_pending_count/still_pending_packages are now scoped by the playbook itself --
// when security_only_update was true for this run, they only reflect still-pending SECURITY
// packages (the actual job this run was responsible for), not the full backlog. otherPendingCount/
// otherPendingPackages carry whatever's still pending OUTSIDE that scope (e.g. non-security
// updates on a security-only run), purely for informational messaging -- Patch Outcome's
// stillPendingCount > 0 check is untouched and now judges success/partial against the right scope.
const targetHostname = $('Decide Template + Lock Key').first().json.hostname;
const text = ($input.first().json.output || '').replace(/\\"/g, '"');
const re = /PATCH_VERIFY_JSON:\s*(\{.*\})/g;
let m;
const candidates = [];
while ((m = re.exec(text)) !== null) {
  try { candidates.push(JSON.parse(m[1])); } catch (e) { /* skip unparsable line */ }
}
let parsed = candidates.find(c => (c.hostname || '').toLowerCase() === (targetHostname || '').toLowerCase());
const matchedCorrectHost = !!parsed;
if (!parsed) parsed = candidates[0] || {};

return [{ json: {
  ...$('Decide Template + Lock Key').first().json,
  ansibleStatus: $input.first().json.status,
  taskOutput: text,
  stillPendingCount: (parsed.still_pending_count !== undefined ? parsed.still_pending_count : -1),
  stillPendingPackages: parsed.still_pending_packages || [],
  otherPendingCount: parsed.other_pending_count || 0,
  otherPendingPackages: parsed.other_pending_packages || [],
  agentPresent: !!parsed.agent_present,
  patchResultHostCount: candidates.length,
  patchResultMatchedCorrectHost: matchedCorrectHost
} }];

