// Parses the MAINTENANCE_RESULT_JSON line the uptimekuma_maintenance.yml playbook
// prints, e.g.
// MAINTENANCE_RESULT_JSON: {"hostname":"web1","action":"start","kumaEnabled":true,
//   "instancesConfigured":3,"instancesAttempted":3,"instancesOk":3,
//   "monitorsMatchedTotal":4,"results":[...]}
//
// Best-effort by design: this node NEVER blocks or redirects the flow. Whatever
// happened here (Kuma reachable or not, monitors tagged or not), we still go on
// to snapshot/patch the host below -- worst case if this failed is one spurious
// "still down" alert during the maintenance window that should have covered it,
// which is a much better failure mode than blocking a real patch run on your
// monitoring stack being flaky.
//
// Same hostname-matching + quote-unescaping pattern as Parse Tag-Add Result /
// Parse Patch Verify Result, since this Semaphore task template also runs with
// 'hosts: all' + Limit for scoping.
const targetHostname = $('Decide Template + Lock Key').first().json.hostname;
const text = ($input.first().json.output || '').replace(/\\"/g, '"');
const re = /MAINTENANCE_RESULT_JSON:\s*(\{.*\})/g;
let m;
const candidates = [];
while ((m = re.exec(text)) !== null) {
  try { candidates.push(JSON.parse(m[1])); } catch (e) { /* skip unparsable line */ }
}
let parsed = candidates.find(c => (c.hostname || '').toLowerCase() === (targetHostname || '').toLowerCase());
if (!parsed) parsed = candidates[0] || {};

return [{ json: {
  ...$('Decide Template + Lock Key').first().json,
  uptimeKumaEnabled: !!parsed.kumaEnabled,
  uptimeKumaInstancesConfigured: parsed.instancesConfigured || 0,
  uptimeKumaInstancesOk: parsed.instancesOk || 0,
  uptimeKumaMonitorsMatched: parsed.monitorsMatchedTotal || 0,
  uptimeKumaResults: parsed.results || []
} }];

// Same parsing as Parse Maintenance-Start Result, for the 'stop' call. Logged
// for visibility only -- nothing downstream branches on this, Start Tag-Remove
// Task (right after) already gets everything it needs from named-node references,
// not from this node's output shape.
const targetHostname = $('Decide Template + Lock Key').first().json.hostname;
const text = ($input.first().json.output || '').replace(/\\"/g, '"');
const re = /MAINTENANCE_RESULT_JSON:\s*(\{.*\})/g;
let m;
const candidates = [];
while ((m = re.exec(text)) !== null) {
  try { candidates.push(JSON.parse(m[1])); } catch (e) { /* skip unparsable line */ }
}
let parsed = candidates.find(c => (c.hostname || '').toLowerCase() === (targetHostname || '').toLowerCase());
if (!parsed) parsed = candidates[0] || {};

return [{ json: {
  ...$('Decide Template + Lock Key').first().json,
  uptimeKumaStopEnabled: !!parsed.kumaEnabled,
  uptimeKumaStopInstancesOk: parsed.instancesOk || 0
} }];
